const fs = require("fs");
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
  ShadingType, TableOfContents, PageNumber, Header, Footer, PageBreak
} = require("docx");

// ---------- helpers ----------
const BLUE = "1F4E79";
const LIGHT = "D5E8F0";
const GREY = "F2F2F2";
const border = { style: BorderStyle.SINGLE, size: 1, color: "BFBFBF" };
const borders = { top: border, bottom: border, left: border, right: border };

function h1(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(text)] });
}
function h2(text) {
  return new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(text)] });
}
function p(text, opts = {}) {
  return new Paragraph({
    spacing: { after: 140, line: 276 },
    alignment: opts.justify === false ? AlignmentType.LEFT : AlignmentType.JUSTIFIED,
    children: [new TextRun({ text, ...opts })]
  });
}
function bullet(text) {
  return new Paragraph({
    numbering: { reference: "bullets", level: 0 },
    spacing: { after: 80, line: 276 },
    children: parseRuns(text)
  });
}
// allows **bold:** prefix
function parseRuns(text) {
  const m = text.match(/^\*\*(.+?)\*\*(.*)$/);
  if (m) return [new TextRun({ text: m[1], bold: true }), new TextRun(m[2])];
  return [new TextRun(text)];
}
function cell(text, { head = false, w, bold = false } = {}) {
  return new TableCell({
    borders,
    width: { size: w, type: WidthType.DXA },
    shading: { fill: head ? BLUE : "FFFFFF", type: ShadingType.CLEAR },
    margins: { top: 80, bottom: 80, left: 120, right: 120 },
    children: [new Paragraph({
      spacing: { after: 0, line: 264 },
      children: [new TextRun({ text, bold: head || bold, color: head ? "FFFFFF" : "000000", size: 20 })]
    })]
  });
}
function table(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const headRow = new TableRow({
    tableHeader: true,
    children: headers.map((hd, i) => cell(hd, { head: true, w: widths[i] }))
  });
  const bodyRows = rows.map((r, ri) => new TableRow({
    children: r.map((c, i) => new TableCell({
      borders,
      width: { size: widths[i], type: WidthType.DXA },
      shading: { fill: ri % 2 ? GREY : "FFFFFF", type: ShadingType.CLEAR },
      margins: { top: 80, bottom: 80, left: 120, right: 120 },
      children: [new Paragraph({
        spacing: { after: 0, line: 264 },
        children: [new TextRun({ text: c, size: 20, bold: i === 0 })]
      })]
    }))
  }));
  return new Table({
    width: { size: total, type: WidthType.DXA },
    columnWidths: widths,
    rows: [headRow, ...bodyRows]
  });
}
function spacer() { return new Paragraph({ spacing: { after: 80 }, children: [new TextRun("")] }); }

// ---------- content ----------
const children = [];

// Title block
children.push(new Paragraph({
  alignment: AlignmentType.CENTER, spacing: { before: 2400, after: 120 },
  children: [new TextRun({ text: "Technical Decision Breakdown", bold: true, size: 56, color: BLUE })]
}));
children.push(new Paragraph({
  alignment: AlignmentType.CENTER, spacing: { after: 360 },
  children: [new TextRun({ text: "Machine Learning–Based Resume-to-Job Matching System for IT Graduates in Nepal", size: 28, color: "404040" })]
}));
children.push(new Paragraph({
  alignment: AlignmentType.CENTER, spacing: { after: 100 },
  children: [new TextRun({ text: "Final-Year Thesis — Supporting Technical Specification", italics: true, size: 24 })]
}));
children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  children: [new TextRun({ text: "Language · Tech Stack · Models · Pipeline · Defense Notes", size: 22, color: "808080" })]
}));
children.push(new Paragraph({ children: [new PageBreak()] }));

// TOC
children.push(h1("Contents"));
children.push(new TableOfContents("Contents", { hyperlink: true, headingStyleRange: "1-2" }));
children.push(new Paragraph({ children: [new PageBreak()] }));

// 1. How to use
children.push(h1("1. How to Read This Document"));
children.push(p("This document explains every technical choice behind your project so you can defend it in front of a thesis panel. It answers the four questions examiners always ask: what language are you using, what technology sits at each layer, which model does each job, and why you picked it over the alternatives. Each section is written so you can lift the tables and reasoning straight into your methodology and tools chapters."));
children.push(p("A deliberate distinction runs through the whole document: the core system you actually build for the thesis versus the advanced options you mention as future work. Final-year projects fail defenses when they over-promise. Build the solid baseline, get real numbers, and frame the rest as a roadmap. That is what a mature engineer does, and panels reward it."));

// 2. Languages
children.push(h1("2. Programming Languages"));
children.push(p("Use a small, justified set of languages rather than many. Three is the right number for this system, and each one has a clear reason to exist."));
children.push(table(
  ["Language", "Where it is used", "Why this language"],
  [
    ["Python", "All machine learning, NLP, resume parsing, data cleaning, and the backend API", "The richest ecosystem for ML and NLP (scikit-learn, spaCy, transformers). One language for both data science and backend keeps the project simple and maintainable."],
    ["JavaScript", "Frontend web interface for candidates and employers (React)", "Required for interactive browser UI. React is the industry standard and gives you a professional, responsive interface."],
    ["SQL", "Querying and managing structured data in PostgreSQL", "Declarative, reliable, and the correct tool for relational data such as users, jobs, applications, and skill records."],
  ],
  [1700, 3660, 4000]
));
children.push(spacer());
children.push(p("Recommendation: make Python the primary language of the thesis. JavaScript and SQL are supporting languages. If your timeline is tight, you can even ship a simpler frontend (Django templates or Streamlit) and still demonstrate the full ML pipeline — the matching engine is what is being graded, not the CSS.", { }));

// 3. Tech stack by layer
children.push(h1("3. Tech Stack — What Goes Where"));
children.push(p("Think of the system as five layers stacked on top of each other. Data enters at the top, flows down through the intelligence layer, and results are served back to the user. The table below assigns one primary tool to each layer and names a lighter alternative in case your scope or hardware is limited."));
children.push(table(
  ["Layer", "Primary tool", "Role in the system", "Lighter alternative"],
  [
    ["Frontend (UI)", "React.js", "Registration, resume upload, job search, recommendation dashboard", "Django templates / Streamlit"],
    ["Backend (API)", "Django + Django REST Framework", "Business logic, authentication, connects the UI to the ML models", "FastAPI"],
    ["Database", "PostgreSQL", "Stores users, resumes, jobs, extracted skills, applications", "SQLite (dev / demo only)"],
    ["ML / NLP engine", "scikit-learn + spaCy + Sentence-Transformers", "Parsing, skill extraction, embeddings, matching, ranking", "scikit-learn + TF-IDF only"],
    ["Data handling", "pandas + NumPy", "Cleaning, preprocessing, feature tables, numerical operations", "—"],
    ["Visualisation", "Matplotlib + Seaborn", "Heatmaps, skill distribution, clustering plots for analysis chapter", "Plotly"],
    ["Deployment / DevOps", "Docker + Git/GitHub", "Reproducible environment, version control, easy demo", "Local virtualenv"],
  ],
  [1900, 2700, 3260, 1500]
));
children.push(spacer());
children.push(p("This is essentially the stack already named in your report (Python, Django, React, PostgreSQL, scikit-learn, NLTK, Docker, Git), which is good — it means this breakdown is consistent with what you have written. The one upgrade worth making is adding Sentence-Transformers for semantic matching, explained in the next section, and using spaCy alongside NLTK because spaCy's named-entity recognition is stronger and faster for skill extraction."));

// 4. Pipeline + models
children.push(h1("4. The ML / NLP Pipeline — Which Model Does What"));
children.push(p("This is the heart of the thesis and the part panels probe hardest. The system is not one model; it is a pipeline of stages, and a different technique is correct at each stage. Walk through it stage by stage and you will always have an answer to “why did you use that here?”"));

children.push(h2("Stage 1 — Resume ingestion and parsing"));
children.push(p("Candidates upload resumes as PDF or DOCX. You convert them to raw text before anything else can happen. Use pdfminer.six or PyMuPDF for PDFs and python-docx for Word files. No machine learning here — this is deterministic text extraction. State this clearly; examiners like seeing that you know when not to use ML."));

children.push(h2("Stage 2 — Text cleaning and preprocessing"));
children.push(p("Raw resume text is messy: inconsistent casing, bullet symbols, dates, headers, and local formatting quirks. Clean it with spaCy and regular expressions — lowercasing, tokenisation, stop-word removal, and normalising skill spellings (for example “ReactJS”, “React.js”, and “React JS” all map to one token). For the Nepal context, this stage is where you handle the varied terminology your report mentions, so give it real attention in your methodology."));

children.push(h2("Stage 3 — Skill and entity extraction"));
children.push(p("Now you pull structured information out of the cleaned text: skills, education, job titles, years of experience. The right tool is Named Entity Recognition (NER). Start with a hybrid approach that is both accurate and easy to defend: a curated skill dictionary (a gazetteer of IT skills relevant to Nepal) combined with spaCy's NER. The dictionary guarantees you catch known skills; the NER model generalises to phrasing you did not anticipate. If time allows, fine-tune a custom spaCy NER model on your labelled resumes — but the hybrid baseline alone is a legitimate, publishable method."));

children.push(h2("Stage 4 — Turning text into numbers (representation)"));
children.push(p("A model cannot compare a resume to a job description as raw text; both must become numeric vectors. You have two levels here, and the contrast between them is one of the strongest points you can make in your defense."));
children.push(table(
  ["Method", "What it captures", "Use as"],
  [
    ["TF-IDF (scikit-learn)", "Keyword overlap and term importance. Fast, simple, fully explainable.", "Your baseline — proves the problem and gives a number to beat."],
    ["Sentence-BERT embeddings", "Meaning and context. Knows “TensorFlow” relates to “deep learning” even with no shared keyword.", "Your main model — solves the exact problem in your statement."],
  ],
  [2900, 4360, 2100]
));
children.push(spacer());
children.push(p("This directly answers the problem in your report — the candidate with a TensorFlow project being missed for a machine-learning role because the keyword did not match. TF-IDF would miss that candidate; Sentence-BERT would catch them because it understands the two concepts are semantically related. Showing the baseline failing and the semantic model succeeding on that exact example is a powerful result for your thesis."));

children.push(h2("Stage 5 — Matching and ranking"));
children.push(p("With both resumes and jobs as vectors, you compute how well each candidate fits each job. Use cosine similarity on the Sentence-BERT embeddings to produce a relevance score, then rank jobs for a candidate (and candidates for a job) by that score. To go further, add a supervised ranking model — Random Forest or Gradient Boosted Trees (XGBoost/LightGBM) — that combines the similarity score with structured features such as years of experience, education level, and skill-count overlap to produce a final, learned match score. This is the hybrid, content-based plus collaborative approach your report already describes."));
children.push(table(
  ["Task in the pipeline", "Model / technique", "Why it is the right choice"],
  [
    ["Parsing files to text", "pdfminer / python-docx", "Deterministic; ML is unnecessary and would add error."],
    ["Skill / entity extraction", "Skill dictionary + spaCy NER", "Combines guaranteed recall with generalisation; defensible baseline."],
    ["Text representation", "TF-IDF (baseline), Sentence-BERT (main)", "Baseline for comparison; semantic model solves the keyword problem."],
    ["Similarity scoring", "Cosine similarity", "Standard, interpretable measure of vector closeness."],
    ["Final match ranking", "Random Forest / Gradient Boosting", "Handles mixed features, robust, gives feature importance for explainability."],
  ],
  [2700, 2860, 3800]
));
children.push(spacer());

children.push(h2("Stage 6 — Evaluation"));
children.push(p("You must measure the system, not just build it. Report precision, recall, and F1-score for skill extraction and matching, and use ranking metrics — Mean Average Precision (MAP) and NDCG — to judge whether the right jobs appear near the top of each candidate's list. Compare your semantic model against the TF-IDF baseline so improvement is quantified. This evaluation section is often the difference between an average and a strong thesis grade."));

// 5. Why this works for Nepal
children.push(h1("5. Why This Stack Fits the Nepal Context"));
children.push(p("Your project's contribution is local relevance, so tie the technology back to it. Three choices carry that argument."));
children.push(bullet("**Hybrid skill extraction (dictionary + NER):** a Nepal-specific skill dictionary lets you encode local terminology and the real skills employers ask for, which global platforms ignore."));
children.push(bullet("**Semantic matching over keywords:** local resumes use varied wording for the same competency, exactly the case where Sentence-BERT beats keyword filters."));
children.push(bullet("**Lightweight, open-source stack:** every tool here is free and runs on modest hardware, which matters for a system built and demonstrated locally without cloud budgets."));

// 6. Recommended scope
children.push(h1("6. Recommended Scope — Build vs. Future Work"));
children.push(p("Protect your timeline by being explicit about the boundary between what you build and what you propose. A focused, working system beats an ambitious, half-finished one every time."));
children.push(table(
  ["Build for the thesis (core)", "Mention as future work"],
  [
    ["Resume upload + text parsing", "Mobile app / large-scale deployment"],
    ["Hybrid skill extraction", "Custom fine-tuned transformer NER"],
    ["TF-IDF baseline + Sentence-BERT matching", "True collaborative filtering at scale"],
    ["Cosine similarity ranking + simple supervised re-ranker", "Real-time learning from live user feedback"],
    ["Evaluation with precision/recall/F1 + baseline comparison", "Longitudinal study of career outcomes"],
    ["Basic web UI for both user types", "Employer analytics dashboard with live data"],
  ],
  [4680, 4680]
));

// 7. Defense prep
children.push(h1("7. Defense Preparation — Likely Questions"));
children.push(p("Rehearse short, confident answers to the questions a panel is most likely to ask. Below are the common ones with the line of reasoning to take."));
children.push(bullet("**Why not just use keyword matching?** It misses semantically related skills — a TensorFlow project not matched to a machine-learning role. Sentence-BERT captures meaning, which my results quantify against a TF-IDF baseline."));
children.push(bullet("**Why Random Forest and not deep learning for ranking?** With a limited local dataset, tree ensembles are more robust, less prone to overfitting, train fast, and give feature importance for explainability — all of which suit a final-year scope."));
children.push(bullet("**How do you handle bias and fairness?** Skills-based features only, no protected attributes in the model, fairness checks across groups, and transparent, logged scoring so recommendations can be audited."));
children.push(bullet("**Why is this better than LinkedIn or Indeed?** Local terminology in the skill dictionary, semantic matching tuned to Nepali IT resumes, and a free, lightweight stack — the local fit global platforms do not provide."));
children.push(bullet("**Where did your data come from and is it enough?** Resumes and postings from local universities and IT firms, with data augmentation and clear preprocessing for incomplete resumes; the baseline-versus-semantic comparison holds even on a modest dataset."));

children.push(spacer());
children.push(new Paragraph({
  spacing: { before: 200 },
  border: { top: { style: BorderStyle.SINGLE, size: 6, color: BLUE, space: 6 } },
  children: [new TextRun({ text: "Summary: Python-first, three-language stack; Django/React/PostgreSQL around a scikit-learn + spaCy + Sentence-BERT engine; a six-stage pipeline with the right model at each stage; TF-IDF baseline beaten by semantic matching; and a clear build-vs-future-work boundary that keeps the thesis achievable.", italics: true, size: 20, color: "404040" })]
}));

// ---------- document ----------
const doc = new Document({
  styles: {
    default: { document: { run: { font: "Calibri", size: 22 } } },
    paragraphStyles: [
      { id: "Heading1", name: "Heading 1", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 30, bold: true, font: "Calibri", color: BLUE },
        paragraph: { spacing: { before: 320, after: 160 }, outlineLevel: 0 } },
      { id: "Heading2", name: "Heading 2", basedOn: "Normal", next: "Normal", quickFormat: true,
        run: { size: 25, bold: true, font: "Calibri", color: "2E5496" },
        paragraph: { spacing: { before: 200, after: 100 }, outlineLevel: 1 } },
    ]
  },
  numbering: {
    config: [
      { reference: "bullets", levels: [{ level: 0, format: LevelFormat.BULLET, text: "•",
        alignment: AlignmentType.LEFT, style: { paragraph: { indent: { left: 540, hanging: 270 } } } }] },
    ]
  },
  sections: [{
    properties: { page: { size: { width: 12240, height: 15840 },
      margin: { top: 1440, right: 1440, bottom: 1440, left: 1440 } } },
    footers: { default: new Footer({ children: [new Paragraph({
      alignment: AlignmentType.CENTER,
      children: [new TextRun({ text: "Technical Decision Breakdown   |   Page ", size: 18, color: "808080" }),
        new TextRun({ children: [PageNumber.CURRENT], size: 18, color: "808080" })]
    })] }) },
    children
  }]
});

Packer.toBuffer(doc).then(buffer => {
  fs.writeFileSync("Technical_Decision_Breakdown.docx", buffer);
  console.log("written");
});

